// n8n Code node ("Run Once for Each Item"), placed right after the Chat Trigger / Telegram Trigger.
// Detects the reply language (ru / de / en) from the visitor's OWN words, deterministically,
// so the LLM never has to guess. Output fields go into the AI Agent's system message:
//   ...rules + knowledge...
//   REPLY LANGUAGE: {{ $json.reply_language_name }}. Write every sentence in this language.
//
// Fallback chain when the text itself has too little signal ("ok", "Hi", a link):
//   prev_lang (language of the previous turn, sent by the web page) → hint (browser language /
//   Telegram message.from.language_code) → English.

const DE = new Set(('der die das und ist nicht sie ich wir ein eine einen mit für auf wie hat haben sind zu den dem ' +
  'auch kann können bitte über ihr ihre welche welcher warum wer gibt es noch mehr oder aber bei von nach ' +
  'stelle erfahrung arbeitet gebaut projekt projekte hallo danke guten tag servus erzählen sie mir diese dieser ' +
  'kenntnisse deutsch passt woran arbeitet gerade').split(' '));
const EN = new Set(('the and is are not she he i we a an with for on how what has have to of it can please about ' +
  'her which why who does did there more or but at from this that built work working experience role hi hello ' +
  'thanks thank yes tell me job position fit would could should').split(' '));

function scoreOf(s) {
  const cyr = (s.match(/[а-яё]/gi) || []).length;
  const lat = (s.match(/[a-zäöüß]/gi) || []).length;
  const words = s.toLowerCase().match(/[a-zäöüß]+/g) || [];
  let de = 0, en = 0;
  for (const w of words) { if (DE.has(w)) de++; if (EN.has(w)) en++; }
  de += ((s.match(/[äöüß]/gi) || []).length) * 2;
  return { cyr, lat, de, en, n: words.length };
}

function decide(s) {
  const x = scoreOf(s);
  if (x.cyr >= 3 && x.cyr >= x.lat * 0.3) return 'ru';
  const need = x.n <= 3 ? 1 : 2;           // short messages: one clear word is enough
  if (Math.max(x.de, x.en) < need || x.de === x.en) return null;
  return x.de > x.en ? 'de' : 'en';
}

function detectLanguage(text, prevLang, hint) {
  const t = String(text || '').trim();
  // the visitor's own words usually come first: first sentence (or line), then the whole text
  const head = (t.match(/^[\s\S]{3,200}?[?!.\n]/) || [t.slice(0, 200)])[0];
  const norm = (l) => (l || '').toLowerCase().slice(0, 2);
  return decide(head) || decide(t) ||
    (['ru', 'de', 'en'].includes(norm(prevLang)) ? norm(prevLang) : null) ||
    (['ru', 'de', 'en'].includes(norm(hint)) ? norm(hint) : null) || 'en';
}

const NAMES = { ru: 'Russian (русский)', de: 'German (Deutsch, formal "Sie")', en: 'English' };

// ── n8n glue ────────────────────────────────────────────────────────
if (typeof $input !== 'undefined') {
  const j = $input.item.json;
  const text = j.chatInput ?? j.message?.text ?? '';
  const hint = j.lang_hint ?? j.message?.from?.language_code ?? '';
  const lang = detectLanguage(text, j.prev_lang, hint);
  return { json: { ...j, reply_language: lang, reply_language_name: NAMES[lang] } };
}

// n8n Code node "Guard" ("Run Once for Each Item"), placed right after "Detect language".
// Protects the Anthropic budget on a public chat: the question goes to Claude only if
//   - the message is not too long,
//   - this conversation (sessionId) has not used up its questions for today,
//   - the whole assistant has not used up its questions for today (sessionIds are set by the browser,
//     so an attacker could invent new ones — the daily total is the real brake).
// Counters live in the workflow's static data: they are saved only for production runs of the
// published workflow (not for test-chat runs in the editor) and reset every day (UTC).

const MAX_PER_SESSION = 20;    // questions per conversation per day
const MAX_PER_DAY = 100;       // questions for the whole assistant per day (≈ $3.5 at ~3.5¢ each)
const MAX_CHARS = 1500;        // a question or the key requirements of a job, not a full vacancy

const TEXT = {
  session: {
    ru: 'Спасибо за интерес! В этом разговоре закончился лимит вопросов. Чтобы продолжить, напишите Вильдане напрямую: меню «Let\'s talk» вверху страницы.',
    de: 'Vielen Dank für Ihr Interesse! Das Fragenlimit für dieses Gespräch ist erreicht. Bitte schreiben Sie Vildana direkt über „Let\'s talk“ oben auf der Seite.',
    en: "Thanks for your interest! This conversation has reached its question limit. To continue, please contact Vildana directly via “Let's talk” at the top of the page.",
  },
  daily: {
    ru: 'Сегодня ассистент уже ответил на много вопросов и отдыхает до завтра. Напишите Вильдане напрямую: меню «Let\'s talk» вверху страницы.',
    de: 'Der Assistent hat heute schon viele Fragen beantwortet und ist ab morgen wieder da. Bitte schreiben Sie Vildana direkt über „Let\'s talk“ oben auf der Seite.',
    en: "The assistant has answered many questions today and will be back tomorrow. Please contact Vildana directly via “Let's talk” at the top of the page.",
  },
  too_long: {
    ru: 'Сообщение слишком длинное. Пожалуйста, сократите его до 1500 символов: для вакансии достаточно ключевых требований.',
    de: 'Die Nachricht ist zu lang. Bitte kürzen Sie sie auf 1.500 Zeichen: Für eine Stelle genügen die wichtigsten Anforderungen.',
    en: 'The message is too long. Please keep it under 1,500 characters: for a job, the key requirements are enough.',
  },
};

function guard(j, store) {
  const today = new Date().toISOString().slice(0, 10);
  if (store.day !== today) { store.day = today; store.total = 0; store.sessions = {}; }
  // Migration of counters written before the 's:' prefix (v1.2, 2026-09-25): merge them, so a conversation keeps its count.
  for (const k of Object.keys(store.sessions)) {
    if (k.startsWith('s:')) continue;
    const nk = 's:' + k;
    store.sessions[nk] = (Object.prototype.hasOwnProperty.call(store.sessions, nk) ? store.sessions[nk] : 0) + store.sessions[k];
    delete store.sessions[k];
  }
  const sid = 's:' + String(j.sessionId || 'anonymous').slice(0, 64);   // prefixed key: 'constructor' / '__proto__' cannot escape the per-session cap
  const used = Object.prototype.hasOwnProperty.call(store.sessions, sid) ? store.sessions[sid] : 0;
  const text = String(j.chatInput ?? j.message?.text ?? '');

  let reason = null;
  if (text.length > MAX_CHARS) reason = 'too_long';
  else if (store.total >= MAX_PER_DAY) reason = 'daily';
  else if (used >= MAX_PER_SESSION) reason = 'session';

  if (!reason) { store.sessions[sid] = used + 1; store.total += 1; }
  const lang = j.reply_language || 'en';
  return {
    ...j,
    blocked: Boolean(reason),
    block_reason: reason || '',
    limit_reply: reason ? (TEXT[reason][lang] || TEXT[reason].en) : '',
    questions_today: store.total,
  };
}

// ── n8n glue ────────────────────────────────────────────────────────
if (typeof $input !== 'undefined') {
  return { json: guard($input.item.json, $getWorkflowStaticData('global')) };
}

// Runs when the AI Agent fails (e.g. Anthropic credit balance is empty, API down).
// Visitors get a polite answer in their language instead of an error.
const lang = $('Detect language').item.json.reply_language || 'en';
const TEXT = {
  ru: 'Извините, ассистент сейчас недоступен. Напишите Вильдане напрямую: кнопка «Let\'s talk» вверху страницы.',
  de: 'Entschuldigung, der Assistent ist gerade nicht erreichbar. Bitte kontaktieren Sie Vildana direkt über „Let\'s talk“ oben auf der Seite.',
  en: "Sorry, the assistant is unavailable right now. Please reach Vildana directly via “Let's talk” at the top of the page.",
};
// The error itself stays in the n8n execution log; visitors get only the text and the language.
return { json: { output: TEXT[lang] || TEXT.en, lang } };
